#!/usr/bin/env node
/**
 * Operator approval request CLI
 *
 * Reads a ComplexityExecutionPlanPreflightSealPacket from a JSON file and outputs
 * the rendered operator approval request markdown to stdout.
 *
 * Usage:
 *   node scripts/operator-approval-request.mjs <input.json> [--pretty]
 *
 * The input JSON file should contain a ComplexityExecutionPlanPreflightSealPacket
 * as generated by scripts/complexity-execution-plan-preflight-seal.mjs or the
 * buildComplexityExecutionPlanPreflightSeal function.
 *
 * Safety: This is a source-only, no-live tool. It only reads input and
 * prints rendered output. It does NOT:
 *   - Grant or dispatch approval
 *   - Execute, dispatch, or seal plans
 *   - Mutate DB, deploy, or restart services
 *   - Move secrets or perform ACK/replay
 *   - Open execution windows
 *   - Send provider messages
 */
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..");

async function main() {
  const args = process.argv.slice(2);
  const pretty = args.includes("--pretty");

  if (args.length === 0 || args[0] === "--help" || args[0] === "-h") {
    console.error("Usage: node scripts/operator-approval-request.mjs <input.json> [--pretty]");
    console.error("");
    console.error("Reads a ComplexityExecutionPlanPreflightSealPacket from a JSON file and");
    console.error("outputs the rendered operator approval request markdown to stdout.");
    process.exitCode = 1;
    return;
  }

  const inputPath = args[0];

  // Read input JSON
  let seal;
  try {
    const raw = readFileSync(inputPath, "utf-8");
    seal = JSON.parse(raw);
  } catch (err) {
    console.error(`Error reading input file "${inputPath}":`, err.message);
    process.exitCode = 1;
    return;
  }

  // Validate kind
  if (seal.kind !== "a2a-broker.complexity-execution-plan-preflight-seal.packet") {
    console.error(
      `Expected seal.kind "a2a-broker.complexity-execution-plan-preflight-seal.packet", ` +
      `got "${seal.kind}". Is this a valid complexity execution plan preflight seal?`,
    );
    process.exitCode = 1;
    return;
  }

  // Import the module
  const {
    buildOperatorApprovalRequestFromPreflightSeal,
    renderOperatorApprovalRequestMarkdown,
  } = await import(
    join(REPO_ROOT, "dist/core/operator-approval-request.js")
  );

  // Build the approval request
  const request = buildOperatorApprovalRequestFromPreflightSeal(seal);

  // Render and output
  const markdown = renderOperatorApprovalRequestMarkdown(request);

  if (pretty) {
    // Pretty-print with section borders
    const border = "─".repeat(60);
    const lines = markdown.split("\n");
    console.log(border);
    for (const line of lines) {
      console.log(line);
    }
    console.log(border);
  } else {
    process.stdout.write(markdown);
    process.stdout.write("\n");
  }
}

main().catch((err) => {
  console.error("Operator approval request CLI failed:", err);
  process.exitCode = 1;
});
